<template><ScrollViewer class="gallery-page-scroll" VerticalScrollBarVisibility="Auto" VerticalScrollMode="Auto"><StackPanel class="gallery-item-page"><StackPanel class="page-heading"><TextBlock class="page-header" Text="{x:Bind $t('text.treeview'), Mode=OneWay}" /><TextBlock class="page-description" Text="{x:Bind $t('text.the-treeview-control-is-a-hierarchical-list-patt'), Mode=OneWay}" TextWrapping="WrapWholeWords" /><StackPanel class="page-header-actions" Orientation="Horizontal"><Button class="header-action" Click="toggleTheme"><TextBlock class="icon" Text="&#xE793;" /></Button><ToggleButton class="header-action" IsChecked="{x:Bind isFavoriteState, Mode=TwoWay}" Click="toggleFavorite"><TextBlock class="icon" Text="{x:Bind favoriteGlyph, Mode=OneWay}" /></ToggleButton></StackPanel></StackPanel><StackPanel class="gallery-page-content">
<ControlExample HeaderText="{x:Bind $t('sample.treeview.drag-drop'), Mode=OneWay}" Theme="{x:Bind pageTheme, Mode=OneWay}" Xaml="{x:Bind simpleXaml, Mode=OneWay}"><ControlExample.Example><Grid Height="280" BorderBrush="{ThemeResource TextControlBorderBrush}" BorderThickness="1"><TreeView MinWidth="345" MaxHeight="400" Margin="0,12,0,0" HorizontalAlignment="Center" VerticalAlignment="Top" ItemsSource="{x:Bind simpleTree, Mode=TwoWay}" AllowDrop="{x:Bind allowDrop, Mode=OneWay}" CanDragItems="{x:Bind canDrag, Mode=OneWay}"><TreeView.ItemTemplate><DataTemplate><TextBlock Text="{x:Bind Content}" /></DataTemplate></TreeView.ItemTemplate></TreeView></Grid></ControlExample.Example><ControlExample.Options><StackPanel><CheckBox IsChecked="{x:Bind canDrag, Mode=TwoWay}"><TextBlock Text="{x:Bind $t('sample.can-drag-items'), Mode=OneWay}" /></CheckBox><CheckBox IsChecked="{x:Bind allowDrop, Mode=TwoWay}"><TextBlock Text="{x:Bind $t('sample.allow-drop'), Mode=OneWay}" /></CheckBox></StackPanel></ControlExample.Options></ControlExample>
<ControlExample HeaderText="{x:Bind $t('sample.treeview.multi-selection'), Mode=OneWay}" Theme="{x:Bind pageTheme, Mode=OneWay}" Xaml="{x:Bind multipleXaml, Mode=OneWay}"><ControlExample.Example><Grid Height="280" BorderBrush="{ThemeResource TextControlBorderBrush}" BorderThickness="1"><TreeView MinWidth="345" MaxHeight="400" Margin="0,12,0,0" HorizontalAlignment="Center" VerticalAlignment="Top" ItemsSource="{x:Bind multiTree, Mode=TwoWay}" SelectionMode="Multiple"><TreeView.ItemTemplate><DataTemplate><TextBlock Text="{x:Bind Content}" /></DataTemplate></TreeView.ItemTemplate></TreeView></Grid></ControlExample.Example></ControlExample>
<ControlExample HeaderText="{x:Bind $t('sample.treeview.databinding-itemsource'), Mode=OneWay}" Theme="{x:Bind pageTheme, Mode=OneWay}" Xaml="{x:Bind bindingXaml, Mode=OneWay}"><ControlExample.Example><Grid Height="200" BorderBrush="{ThemeResource TextControlBorderBrush}" BorderThickness="1"><TreeView MinWidth="345" MaxHeight="400" Margin="0,12,0,0" HorizontalAlignment="Center" VerticalAlignment="Top" ItemsSource="{x:Bind dataSource, Mode=OneWay}"><TreeView.ItemTemplate><DataTemplate><TextBlock Text="{x:Bind Name}" /></DataTemplate></TreeView.ItemTemplate></TreeView></Grid></ControlExample.Example></ControlExample>
<ControlExample HeaderText="{x:Bind $t('sample.treeview.item-template-selector'), Mode=OneWay}" Theme="{x:Bind pageTheme, Mode=OneWay}" Xaml="{x:Bind selectorXaml, Mode=OneWay}"><ControlExample.Example><Grid Height="200" BorderBrush="{ThemeResource TextControlBorderBrush}" BorderThickness="1"><TreeView MinWidth="345" MaxHeight="400" Margin="0,12,0,0" HorizontalAlignment="Center" VerticalAlignment="Top" ItemsSource="{x:Bind dataSource, Mode=OneWay}" ItemTemplateSelector="{x:Bind selector}"><TreeView.ItemTemplate><DataTemplate><StackPanel Orientation="Horizontal"><TextBlock Text="{x:Bind Type}" /><TextBlock Margin="8,0,0,0" Text="{x:Bind Name}" /></StackPanel></DataTemplate></TreeView.ItemTemplate></TreeView></Grid></ControlExample.Example></ControlExample>
</StackPanel></StackPanel></ScrollViewer></template>
<script setup>
import { computed, h, inject, ref } from 'vue'; import Button from '../../components/Button.vue'; import CheckBox from '../../components/CheckBox.vue'; import ControlExample from '../../components/ControlExample.vue'; import FontIcon from '../../components/FontIcon.vue'; import Grid from '../../components/Grid.vue'; import ScrollViewer from '../../components/ScrollViewer.vue'; import StackPanel from '../../components/StackPanel.vue'; import TextBlock from '../../components/TextBlock.vue'; import ToggleButton from '../../components/ToggleButton.vue'; import TreeView from '../../components/TreeView.vue'; import { createPageState } from '../../utils/pageState'
const currentPage = inject('currentPage'); const pageKey = computed(() => currentPage?.value || 'treeview'); const { isFavoriteState, pageTheme, toggleTheme, toggleFavorite } = createPageState(pageKey.value); const favoriteGlyph = computed(() => isFavoriteState.value ? '\uE735' : '\uE734'); const makeTree = () => [{ Content: 'Work Documents', IsExpanded: true, Children: [{ Content: 'XYZ Functional Spec' }, { Content: 'Feature Schedule' }] }, { Content: 'Personal Documents', IsExpanded: true, Children: [{ Content: 'Home Remodel', IsExpanded: true, Children: [{ Content: 'Contractor Contact Info' }, { Content: 'Paint Color Scheme' }] }] }]; const simpleTree = ref(makeTree()); const multiTree = ref(makeTree()); const canDrag = ref(true); const allowDrop = ref(true); const dataSource = ref([{ Name: 'Documents', Type: 'Folder', IsExpanded: true, Children: [{ Name: 'ProjectProposal', Type: 'File' }, { Name: 'BudgetReport', Type: 'File' }] }, { Name: 'Projects', Type: 'Folder', IsExpanded: true, Children: [{ Name: 'Project Plan', Type: 'File' }] }]);
const FolderTemplate = { props: { Item: { type: Object, default: () => ({}) } }, setup(props) { return () => h(StackPanel, { Orientation: 'Horizontal' }, () => [h(FontIcon, { Glyph: '\uE8B7' }), h(TextBlock, { Margin: '8,0,0,0', Text: props.Item?.Name ?? '' })]) } }; const FileTemplate = { props: { Item: { type: Object, default: () => ({}) } }, setup(props) { return () => h(StackPanel, { Orientation: 'Horizontal' }, () => [h(FontIcon, { Glyph: '\uE8A5' }), h(TextBlock, { Margin: '8,0,0,0', Text: props.Item?.Name ?? '' })]) } }; const selector = { SelectTemplate: (item) => item.Type === 'Folder' ? FolderTemplate : FileTemplate }; const simpleXaml = '<TreeView x:Name="sampleTreeView" CanDragItems="True" AllowDrop="True" />'; const multipleXaml = '<TreeView x:Name="sampleTreeView2" SelectionMode="Multiple" />'; const bindingXaml = '<TreeView ItemsSource="{x:Bind DataSource}"><TreeView.ItemTemplate><DataTemplate><TreeViewItem ItemsSource="{x:Bind Children}" Content="{x:Bind Name}" /></DataTemplate></TreeView.ItemTemplate></TreeView>'; const selectorXaml = '<TreeView ItemsSource="{x:Bind DataSource}" ItemTemplateSelector="{StaticResource ExplorerItemTemplateSelector}" />'
</script><style scoped>.page-heading{position:relative}.page-header{font-size:28px;font-weight:600;margin:0 0 8px}.page-description{color:var(--text-secondary);margin:0 72px 16px 0}.page-header-actions{position:absolute;top:0;right:0;gap:4px}.icon{font-size:16px}</style>
